function tests(){const checks=[],check=(name,fn)=>{try{if(!fn())throw Error('结果不符');checks.push({name,passed:true});}catch(e){checks.push({name,passed:false,error:e.message});}};const cp=[{name:'骑行',trips:100,km:5,base:.12,green:.02}],bp={initial:.3,incentive:1,costSaving:1,extraMinutes:10,timeValue:12,comfort:0,carbonPrice:0,carbonKg:.5,response:.06,rounds:30},fp={baseline:2934.75,paidOrdersWan:30,freeOrdersWan:0,price:2.16,cost:1,compensation:0,contractVerified:false,capex:0,workingCapital:0,otherCash:0};
check('碳核算：100次×5公里＝50 kg',()=>carbon(cp).reductionKg===50);check('里程减半，减排差额减半',()=>carbon([{...cp[0],km:2.5}]).reductionKg===25);check('允许排放上升的负减排值',()=>carbon([{...cp[0],green:.14}]).reductionKg===-10);check('零出行不产生减排',()=>carbon([{...cp[0],trips:0}]).reductionKg===0);check('碳核算拒绝负里程',()=>{try{carbon([{...cp[0],km:-1}]);return false;}catch{return true;}});check('行为模型零收益差保持初始占比',()=>Math.abs(behavior(bp).finalShare-.3)<1e-10);check('正激励提高模型内占比',()=>behavior({...bp,incentive:2}).finalShare>.3);check('边界初始占比为0时保持0',()=>behavior({...bp,initial:0}).finalShare===0);check('高负收益不会溢出',()=>Number.isFinite(behavior({...bp,incentive:0,costSaving:-100}).finalShare));check('财务收入64.80万元',()=>finance(fp).deltaRevenueWan===64.8);check('经营贡献34.80万元',()=>finance(fp).contributionWan===34.8);check('免费无补偿不计收入',()=>finance({...fp,paidOrdersWan:0,freeOrdersWan:30}).deltaRevenueWan===0);check('免费订单成本不消失',()=>finance({...fp,paidOrdersWan:0,freeOrdersWan:30}).contributionWan===-30);check('未核实补偿不计收入',()=>finance({...fp,compensation:12}).deltaRevenueWan===64.8);check('核实补偿要求依据说明',()=>{try{finance({...fp,compensation:12,contractVerified:true});return false;}catch{return true;}});check('缺成本时不输出经营贡献',()=>finance({...fp,cost:null}).contributionWan===null);check('不同研究基准正确更新总收入',()=>finance({...fp,baseline:100}).totalRevenueWan===164.8);check('现金支出不等同利润',()=>finance({...fp,capex:10,workingCapital:5}).cashAfterInputsWan===19.8);check('CSV引号解析',()=>parseCSV('a,b\n"x,y",2')[1][0]==='x,y');check('完整出行CSV可复算',()=>carbon(carbonCSV('方式,次数,单次公里,基准因子,情景因子\n骑行,100,5,0.12,0.02')).reductionKg===50);check('CSV拒绝缺失值',()=>{try{carbonCSV('方式,次数,单次公里,基准因子,情景因子\n骑行,,5,.12,.02');return false;}catch{return true;}});check('检索保留原页码',()=>search([{id:'d',title:'材料',pages:[{page:58,text:'常州收入2934.75万元'}]}],'常州')[0].page===58);check('政策目标不自动标为事实',()=>candidates({id:'d',pages:[{page:1,text:'到2030年，绿色出行比例达到80%。'}]})[0].type==='政策目标');check('敏感性矩阵中央格对应当前情景',()=>sensitivity(fp).cells[2][2]===finance(fp).contributionWan);return checks;}
return {version,carbon,behavior,finance,scenarioSet,sensitivity,hash,search,candidates,parseCSV,carbonCSV,safeCSV,report,tests};
